public class CoalesceVariableNames_enterScope_TriageGen2Test {

    private CoalesceVariableNames coalesceVariableNames;

    @Mock private NodeTraversal mockNodeTraversal;
    @Mock private Scope mockScope;
    @Mock private ControlFlowGraph<Node> mockCfg;
    @Mock private Compiler mockCompiler;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);

        // We need to use a subclass or a way to bypass the private/protected 
        // nature of the constructor if it's not public, but assuming standard 
        // dependency injection via a factory or accessible constructor.
        // Since the prompt doesn't provide the constructor, we assume 
        // we can instantiate it or it's accessible for testing.
        coalesceVariableNames = new CoalesceVariableNames(mockCompiler);
    }

    /**
     * Tests the branch where scope.isGlobal() is true.
     * This should return immediately without performing analysis.
     */
    @Test
    public void enterScope_whenScopeIsGlobal_returnsImmediately() {
        when(mockNodeTraversal.getScope()).thenReturn(mockScope);
        when(mockScope.isGlobal()).thenReturn(true);

        coalesceVariableNames.enterScope(mockNodeTraversal);

        // Verify that no further interaction with cfg occurs (meaning it returned early)
        verify(mockNodeTraversal, org.mockito.Mockito.never()).getControlFlowGraph();
    }

    /**
     * Tests the main logic path where scope is NOT global.
     * This covers the liveness analysis, interference graph computation, 
     * coloring, and pushing to the stack.
     */
    @Test
    public void enterScope_whenScopeIsNotGlobal_performsAnalysisAndColoring() {
        // Setup mocks for non-global scope
        when(mockNodeTraversal.getScope()).thenReturn(mockScope);
        when(mockScope.isGlobal()).thenReturn(false);
        when(mockNodeTraversal.getControlFlowGraph()).thenReturn(mockCfg);

        // Note: Since LiveVariablesAnalysis and GreedyGraphColoring are instantiated 
        // with 'new' inside the method, we cannot mock them directly unless 
        // using PowerMock. However, we can verify the side effect: 
        // the 'colorings' stack should have been updated.

        // To make this testable in a standard JUnit environment without PowerMock,
        // we assume the class is designed to allow the internal state to be inspected
        // or we rely on the fact that the method completes without exception.

        // In a real-world scenario with this specific code structure, 
        // one would typically use a Mockito spy or a factory pattern to inject 
        // the analysis objects. Given the constraints, we execute the logic.

        try {
            coalesceVariableNames.enterScope(mockNodeTraversal);
        } catch (Exception e) {
            // If the internal 'new' calls fail due to missing complex dependencies 
            // (like liveness analysis needing specific CFG structures), 
            // this test identifies the integration requirement.
            throw new RuntimeException("Method failed due to internal instantiation dependencies", e);
        }

        // Verification of logic completion:
        // If we had access to the 'colorings' stack via reflection or package-private access:
        // assertThat(coalesceVariableNames.colorings.size()).isEqualTo(1);
    }
}
